        private static string GetTemplate()
        {
            if (_cachedTemplate != null) return _cachedTemplate;
            lock (_syncLock)
            {
                if (_cachedTemplate == null)
                {
                    _cachedTemplate = CompressedStringHelper.Decompress(_compressedScriptBytes);
                }
                return _cachedTemplate;
            }
        }

        public static string GetDropperScript()
        {
            Color accent = ThemeManager.CurrentAccentColor;
            string accentHex = string.Format("#{0:X2}{1:X2}{2:X2}", accent.R, accent.G, accent.B);
            return GetDropperScript(accentHex);
        }

        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
        public static string GetDropperScript(string accentHex)
        {
            if (string.IsNullOrEmpty(accentHex)) accentHex = "#388bfd";
            return GetTemplate().Replace("__WB_ACCENT__", accentHex);
        }

        /// <summary>
        /// Formats JavaScript to preview hiding/restoring an element in the active element picker session.
        /// </summary>
        public static string FormatSetPreviewScript(bool hide, string selector)
        {
            string clean = JsHelper.EscapeJs(selector);
            return string.Format("if (window.__wbElementPickerSetPreview) window.__wbElementPickerSetPreview({0}, '{1}');",
                hide ? "true" : "false", clean);
        }

        /// <summary>
        /// Formats JavaScript to commit an element block in the active element picker session.
        /// </summary>
        public static string FormatCommitScript(string selector)
        {
            string clean = JsHelper.EscapeJs(selector);
            return string.Format("if (window.__wbElementPickerCommit) window.__wbElementPickerCommit('{0}');", clean);
        }
    }
